CREATE POLICY "registry_authorization_read" ON "events" AS PERMISSIVE FOR SELECT TO "sep_migrator" USING (current_setting('sep.organization_admin', true) = 'true' AND "events"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "registry_authorization_read" ON "memberships" AS PERMISSIVE FOR SELECT TO "sep_migrator" USING (current_setting('sep.organization_admin', true) = 'true' AND "memberships"."organization_id" = nullif(current_setting('sep.organization_id', true), '')::uuid AND "memberships"."person_id" = nullif(current_setting('sep.person_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "registry_authorization_read" ON "people" AS PERMISSIVE FOR SELECT TO "sep_migrator" USING (current_setting('sep.organization_admin', true) = 'true' AND "people"."id" = nullif(current_setting('sep.person_id', true), '')::uuid);--> statement-breakpoint
CREATE POLICY "registry_authorization_read" ON "role_assignments" AS PERMISSIVE FOR SELECT TO "sep_migrator" USING (current_setting('sep.organization_admin', true) = 'true' AND EXISTS (SELECT 1 FROM memberships m WHERE m.id = "role_assignments"."membership_id"));